import React, { useState, useEffect, useRef } from 'react';
import { toast } from 'react-toastify';

import {
  FiPlus,
  FiEdit2,
  FiTrash2,
  FiImage,
  FiHome,
  FiCheckCircle,
} from 'react-icons/fi';

import api from '../../services/api';
import { getImageUrl } from '../../utils/helpers';

import AdminTable from '../common/AdminTable';
import AdminModal from '../common/AdminModal';
import AdminCard from '../common/AdminCard';


// ==========================================
// DEFAULT IMAGE
// ==========================================
const DEFAULT_IMG = '/default-avatar.png';


// ==========================================
// INITIAL FORM
// ==========================================
const initialForm = {
  name: '',
  acronym: '',
  tag: '',
  description: '',
  features: '',
  is_active: true,
  order: 0,
};


// ==========================================
// ADMIN SCHOOLS
// ==========================================
const AdminSchools = () => {

  // ========================================
  // STATES
  // ========================================
  const [schools, setSchools] = useState([]);
  const [loading, setLoading] = useState(true);

  const [modalOpen, setModalOpen] = useState(false);
  const [editingSchool, setEditingSchool] = useState(null);

  const [formData, setFormData] = useState(initialForm);

  const [imageFile, setImageFile] = useState(null);

  const fileRef = useRef(null);


  // ========================================
  // LOAD SCHOOLS
  // ========================================
  useEffect(() => {
    fetchSchools();
  }, []);


  // ========================================
  // FETCH SCHOOLS
  // ========================================
  const fetchSchools = async () => {
    try {

      const res = await api.get('/api/schools/');

      setSchools(res.data || []);

    } catch (error) {

      console.error('Fetch schools error:', error);

      toast.error('Failed to load schools');

    } finally {

      setLoading(false);

    }
  };


  // ========================================
  // RESET FORM
  // ========================================
  const resetForm = () => {

    setEditingSchool(null);

    setFormData({
      name: '',
      acronym: '',
      tag: '',
      description: '',
      features: '',
      is_active: true,
      order: 0,
    });

    setImageFile(null);

    if (fileRef.current) {
      fileRef.current.value = '';
    }
  };


  // ========================================
  // OPEN CREATE MODAL
  // ========================================
  const openCreateModal = () => {

    resetForm();

    setModalOpen(true);
  };


  // ========================================
  // CLOSE MODAL
  // ========================================
  const closeModal = () => {

    setModalOpen(false);

    resetForm();
  };


  // ========================================
  // SUBMIT CREATE / UPDATE
  // ========================================
  const handleSubmit = async (e) => {

    e.preventDefault();

    try {

      const fd = new FormData();

      fd.append('name', formData.name);
      fd.append('acronym', formData.acronym || '');
      fd.append('tag', formData.tag || '');
      fd.append(
        'description',
        formData.description || ''
      );
      fd.append(
        'features',
        formData.features || ''
      );
      fd.append(
        'is_active',
        String(formData.is_active)
      );
      fd.append(
        'order',
        String(formData.order)
      );


      // ====================================
      // IMAGE FILE
      // ====================================
      if (imageFile) {

        fd.append(
          'image_file',
          imageFile
        );

      }


      // ====================================
      // UPDATE
      // ====================================
      if (editingSchool) {

        await api.put(
          `/api/schools/${editingSchool.id}`,
          fd,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );

        toast.success(
          'School updated successfully'
        );

      }

      // ====================================
      // CREATE
      // ====================================
      else {

        await api.post(
          '/api/schools/',
          fd,
          {
            headers: {
              'Content-Type':
                'multipart/form-data',
            },
          }
        );

        toast.success(
          'School created successfully'
        );

      }


      // ====================================
      // CLOSE + REFRESH
      // ====================================
      setModalOpen(false);

      resetForm();

      fetchSchools();

    } catch (error) {

      console.error(
        'School submit error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          'Operation failed'
      );

    }
  };


  // ========================================
  // DELETE SCHOOL
  // ========================================
  const handleDelete = async (id) => {

    const confirmDelete =
      window.confirm(
        'Are you sure you want to delete this school?'
      );

    if (!confirmDelete) {
      return;
    }

    try {

      await api.delete(
        `/api/schools/${id}`
      );

      toast.success(
        'School deleted successfully'
      );

      fetchSchools();

    } catch (error) {

      console.error(
        'Delete school error:',
        error
      );

      toast.error(
        error.response?.data?.detail ||
          'Failed to delete school'
      );

    }
  };


  // ========================================
  // EDIT SCHOOL
  // ========================================
  const handleEdit = (school) => {

    setEditingSchool(school);

    setFormData({
      name: school.name || '',
      acronym: school.acronym || '',
      tag: school.tag || '',
      description:
        school.description || '',
      features:
        school.features || '',
      is_active:
        school.is_active ?? true,
      order:
        school.order || 0,
    });

    setImageFile(null);

    if (fileRef.current) {
      fileRef.current.value = '';
    }

    setModalOpen(true);
  };


  // ========================================
  // TABLE COLUMNS
  // ========================================
  const columns = [

    // ======================================
    // IMAGE
    // ======================================
    {
      key: 'image',
      label: 'Image',

      render: (val) => (

        <div
          className="
            w-20
            h-14
            rounded-xl
            overflow-hidden
            border
            border-blue-200
            bg-blue-50
            shadow-sm
          "
        >

          <img
            src={getImageUrl(
              val,
              DEFAULT_IMG
            )}
            alt="school"
            className="
              w-full
              h-full
              object-cover
            "
            onError={(e) => {
              e.currentTarget.src =
                DEFAULT_IMG;
            }}
          />

        </div>
      ),
    },


    // ======================================
    // ACRONYM
    // ======================================
    {
      key: 'acronym',
      label: 'Acronym',

      render: (val) => (

        <span
          className="
            inline-flex
            items-center
            justify-center

            min-w-[52px]

            px-3
            py-1.5

            rounded-lg

            bg-blue-50
            text-blue-900

            border
            border-blue-200

            text-xs
            font-bold
          "
        >
          {val || '-'}
        </span>
      ),
    },


    // ======================================
    // NAME
    // ======================================
    {
      key: 'name',
      label: 'School Name',

      render: (val) => (

        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          <div
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              flex-shrink-0
            "
          >
            <FiHome size={17} />
          </div>


          <div>

            <p
              className="
                font-semibold
                text-blue-900
              "
            >
              {val || '-'}
            </p>

          </div>

        </div>
      ),
    },


    // ======================================
    // TAG
    // ======================================
    {
      key: 'tag',
      label: 'Tag',

      render: (val) => (

        <span
          className="
            inline-flex

            px-3
            py-1.5

            rounded-full

            bg-blue-50
            text-blue-500

            text-xs
            font-medium
          "
        >
          {val || '-'}
        </span>
      ),
    },


    // ======================================
    // STATUS - Changed Green to Blue
    // ======================================
    {
      key: 'is_active',
      label: 'Status',

      render: (val) => (

        <span
          className={`
            inline-flex
            items-center
            gap-2

            px-3
            py-1.5

            rounded-full

            text-xs
            font-semibold

            border

            ${
              val
                ? `
                  bg-blue-50
                  text-blue-700
                  border-blue-200
                `
                : `
                  bg-red-50
                  text-red-600
                  border-red-200
                `
            }
          `}
        >

          <span
            className={`
              w-2
              h-2
              rounded-full

              ${
                val
                  ? 'bg-blue-500'
                  : 'bg-red-500'
              }
            `}
          />

          {val
            ? 'Active'
            : 'Inactive'}

        </span>
      ),
    },


    // ======================================
    // ACTIONS
    // ======================================
    {
      key: 'actions',
      label: 'Actions',

      render: (_, row) => (

        <div
          className="
            flex
            items-center
            gap-2
          "
        >

          {/* EDIT */}
          <button
            type="button"
            onClick={() =>
              handleEdit(row)
            }
            title="Edit School"
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-blue-50
              text-blue-900

              hover:bg-blue-900
              hover:text-white

              transition-all
              duration-200
            "
          >
            <FiEdit2 size={16} />
          </button>


          {/* DELETE */}
          <button
            type="button"
            onClick={() =>
              handleDelete(row.id)
            }
            title="Delete School"
            className="
              w-9
              h-9

              flex
              items-center
              justify-center

              rounded-lg

              bg-red-50
              text-red-600

              hover:bg-red-600
              hover:text-white

              transition-all
              duration-200
            "
          >
            <FiTrash2 size={16} />
          </button>

        </div>
      ),
    },
  ];


  // ========================================
  // RETURN
  // ========================================
  return (

    <div className="w-full">

      {/* ====================================
          PAGE HEADER
      ==================================== */}
      <div
        className="
          flex
          flex-col
          sm:flex-row

          sm:items-center
          sm:justify-between

          gap-4

          mb-7
        "
      >

        {/* LEFT */}
        <div
          className="
            flex
            items-center
            gap-3
          "
        >

          {/* ICON */}
          <div
            className="
              w-12
              h-12

              flex
              items-center
              justify-center

              rounded-xl

              bg-blue-900
              text-white

              shadow-sm
            "
          >
            <FiHome size={22} />
          </div>


          {/* TITLE */}
          <div>

            <h1
              className="
                text-3xl
                md:text-2xl

                font-bold

                text-blue-900

                leading-tight
              "
            >
              Schools Management
            </h1>

            <p
              className="
                text-sm
                text-blue-400
                mt-1
              "
            >
              Manage school information,
              images and status
            </p>

          </div>

        </div>


        {/* ADD BUTTON */}
        <button
          type="button"
          onClick={openCreateModal}
          className="
            inline-flex
            items-center
            justify-center
            gap-2

            h-11

            px-5

            bg-red-600
            hover:bg-red-700

            text-white

            rounded-xl

            text-sm
            font-semibold

            shadow-sm
            hover:shadow-md

            transition-all
            duration-200
          "
        >
          <FiPlus size={18} />

          Add School
        </button>

      </div>


      {/* ====================================
          TABLE CARD
      ==================================== */}
      <AdminCard
        className="
          overflow-hidden

          bg-white

          border
          border-blue-200

          rounded-2xl

          shadow-sm
        "
      >

        <AdminTable
          columns={columns}
          data={schools}
          loading={loading}
        />

      </AdminCard>


      {/* ====================================
          MODAL
      ==================================== */}
      <AdminModal
        isOpen={modalOpen}
        onClose={closeModal}
        title={
          editingSchool
            ? 'Edit School'
            : 'Create School'
        }
      >

        <form onSubmit={handleSubmit}>

          <div className="space-y-5">

            {/* =================================
                NAME + ACRONYM
            ================================= */}
            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >

              {/* NAME */}
              <div>

                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  School Name

                  <span className="text-red-600 ml-1">
                    *
                  </span>
                </label>

                <input
                  type="text"
                  value={formData.name}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      name:
                        e.target.value,
                    })
                  }
                  className="
                    w-full
                    h-11
                    px-3.5

                    border
                    border-blue-200

                    rounded-xl

                    text-sm
                    text-blue-900

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition-all
                  "
                  placeholder="Enter school name"
                  required
                />

              </div>


              {/* ACRONYM */}
              <div>

                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Acronym
                </label>

                <input
                  type="text"
                  value={
                    formData.acronym
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      acronym:
                        e.target.value,
                    })
                  }
                  className="
                    w-full
                    h-11
                    px-3.5

                    border
                    border-blue-200

                    rounded-xl

                    text-sm
                    text-blue-900

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition-all
                  "
                  placeholder="Example: NLS"
                />

              </div>

            </div>


            {/* =================================
                TAG + ORDER
            ================================= */}
            <div
              className="
                grid
                grid-cols-1
                md:grid-cols-2
                gap-4
              "
            >

              {/* TAG */}
              <div>

                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Tag
                </label>

                <input
                  type="text"
                  value={formData.tag}
                  onChange={(e) =>
                    setFormData({
                      ...formData,
                      tag:
                        e.target.value,
                    })
                  }
                  className="
                    w-full
                    h-11
                    px-3.5

                    border
                    border-blue-200

                    rounded-xl

                    text-sm
                    text-blue-900

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition-all
                  "
                  placeholder="Example: WEG"
                />

              </div>


              {/* ORDER */}
              <div>

                <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                  Display Order
                </label>

                <input
                  type="number"
                  min="0"
                  value={formData.order}
                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      order:
                        parseInt(
                          e.target.value
                        ) || 0,
                    })
                  }
                  className="
                    w-full
                    h-11
                    px-3.5

                    border
                    border-blue-200

                    rounded-xl

                    text-sm
                    text-blue-900

                    outline-none

                    focus:border-blue-900
                    focus:ring-2
                    focus:ring-blue-900/10

                    transition-all
                  "
                />

              </div>

            </div>


            {/* =================================
                DESCRIPTION
            ================================= */}
            <div>

              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Description
              </label>

              <textarea
                value={
                  formData.description
                }
                onChange={(e) =>
                  setFormData({
                    ...formData,

                    description:
                      e.target.value,
                  })
                }
                className="
                  w-full
                  px-3.5
                  py-3

                  border
                  border-blue-200

                  rounded-xl

                  text-sm
                  text-blue-900

                  outline-none
                  resize-none

                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10

                  transition-all
                "
                rows="4"
                placeholder="Write a short description about this school..."
              />

            </div>


            {/* =================================
                FEATURES
            ================================= */}
            <div>

              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                Features
              </label>

              <input
                type="text"
                value={
                  formData.features
                }
                onChange={(e) =>
                  setFormData({
                    ...formData,

                    features:
                      e.target.value,
                  })
                }
                className="
                  w-full
                  h-11
                  px-3.5

                  border
                  border-blue-200

                  rounded-xl

                  text-sm
                  text-blue-900

                  outline-none

                  focus:border-blue-900
                  focus:ring-2
                  focus:ring-blue-900/10

                  transition-all
                "
                placeholder="Modern Classrooms, STEM Programs, Sports"
              />

              <p
                className="
                  text-xs
                  text-blue-300
                  mt-1.5
                "
              >
                Separate each feature
                with a comma.
              </p>

            </div>


            {/* =================================
                IMAGE UPLOAD
            ================================= */}
            <div>

              <label className="block text-sm font-semibold text-blue-900 mb-1.5">
                School Image
              </label>


              <div
                onClick={() =>
                  fileRef.current?.click()
                }
                className="
                  group

                  border-2
                  border-dashed
                  border-blue-200

                  hover:border-blue-900

                  bg-blue-50
                  hover:bg-blue-50

                  rounded-2xl

                  px-5
                  py-7

                  text-center

                  cursor-pointer

                  transition-all
                  duration-200
                "
              >

                {/* FILE INPUT */}
                <input
                  ref={fileRef}
                  type="file"
                  accept="
                    image/jpeg,
                    image/png,
                    image/webp
                  "
                  onChange={(e) =>
                    setImageFile(
                      e.target.files?.[0] ||
                        null
                    )
                  }
                  className="hidden"
                />


                {/* FILE SELECTED */}
                {imageFile ? (

                  <div>

                    <div
                      className="
                        w-14
                        h-14

                        mx-auto
                        mb-3

                        flex
                        items-center
                        justify-center

                        rounded-xl

                        bg-blue-50
                        text-blue-900
                      "
                    >
                      <FiImage size={25} />
                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900

                        break-all
                      "
                    >
                      {imageFile.name}
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-300
                        mt-1
                      "
                    >
                      Click to choose
                      another image
                    </p>

                  </div>

                ) : (

                  /* NO FILE */
                  <div>

                    <div
                      className="
                        w-14
                        h-14

                        mx-auto
                        mb-3

                        flex
                        items-center
                        justify-center

                        rounded-xl

                        bg-white

                        border
                        border-blue-200

                        shadow-sm

                        text-blue-400

                        group-hover:text-blue-900
                        group-hover:scale-105

                        transition-all
                      "
                    >
                      <FiImage size={25} />
                    </div>


                    <p
                      className="
                        text-sm
                        font-semibold
                        text-blue-900
                      "
                    >
                      Click to upload
                      school image
                    </p>


                    <p
                      className="
                        text-xs
                        text-blue-300
                        mt-1
                      "
                    >
                      JPG, PNG or WEBP
                    </p>


                    {/* CURRENT IMAGE */}
                    {editingSchool &&
                      editingSchool.image && (

                        <div
                          className="
                            mt-3

                            inline-flex
                            items-center
                            gap-1.5

                            px-3
                            py-1.5

                            rounded-full

                            bg-blue-50
                            text-blue-900

                            text-xs
                            font-medium
                          "
                        >
                          <FiCheckCircle />

                          Current image will
                          be kept
                        </div>

                      )}

                  </div>

                )}

              </div>

            </div>


            {/* =================================
                STATUS
            ================================= */}
            <div
              className="
                flex
                items-center
                justify-between

                px-4
                py-3.5

                rounded-xl

                bg-blue-50

                border
                border-blue-200
              "
            >

              {/* LEFT */}
              <div>

                <p
                  className="
                    text-sm
                    font-semibold
                    text-blue-900
                  "
                >
                  School Status
                </p>

                <p
                  className="
                    text-xs
                    text-blue-300
                    mt-0.5
                  "
                >
                  Show this school
                  on the website
                </p>

              </div>


              {/* SWITCH */}
              <label
                className="
                  relative
                  inline-flex
                  items-center
                  cursor-pointer
                "
              >

                <input
                  type="checkbox"
                  checked={
                    formData.is_active
                  }
                  onChange={(e) =>
                    setFormData({
                      ...formData,

                      is_active:
                        e.target.checked,
                    })
                  }
                  className="sr-only peer"
                />


                <div
                  className="
                    relative

                    w-11
                    h-6

                    bg-blue-200

                    rounded-full

                    transition-colors

                    peer-checked:bg-blue-900

                    after:content-['']

                    after:absolute
                    after:top-[2px]
                    after:left-[2px]

                    after:w-5
                    after:h-5

                    after:bg-white

                    after:rounded-full

                    after:shadow-sm

                    after:transition-all

                    peer-checked:after:translate-x-full
                  "
                />

              </label>

            </div>

          </div>


          {/* =================================
              FOOTER BUTTONS
          ================================= */}
          <div
            className="
              mt-7
              pt-5

              border-t
              border-blue-200

              flex
              items-center
              justify-end

              gap-3
            "
          >

            {/* CANCEL */}
            <button
              type="button"
              onClick={closeModal}
              className="
                h-11

                px-5

                rounded-xl

                border
                border-blue-200

                bg-white

                text-blue-400

                text-sm
                font-semibold

                hover:bg-blue-50

                transition-all
                duration-200
              "
            >
              Cancel
            </button>


            {/* SUBMIT */}
            <button
              type="submit"
              className="
                h-11

                inline-flex
                items-center
                justify-center
                gap-2

                px-6

                rounded-xl

                bg-red-600
                hover:bg-red-700

                text-white

                text-sm
                font-semibold

                shadow-sm
                hover:shadow-md

                transition-all
                duration-200
              "
            >

              {editingSchool ? (
                <>
                  <FiEdit2 size={16} />

                  Update School
                </>
              ) : (
                <>
                  <FiPlus size={17} />

                  Create School
                </>
              )}

            </button>

          </div>

        </form>

      </AdminModal>

    </div>
  );
};


export default AdminSchools;
